"""
ダイクストラ法 (Dijkstra) & 経路復元 & 01-BFS
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
- dijkstra(n, g, s): 非負の重みをもつグラフの単一始点最短経路 O((V + E) log V)
- dijkstra_path(n, g, s, t): 始点 s から終点 t への最短経路の頂点リストを復元
- bfs01(n, g, s): 重みが 0 または 1 のみのグラフにおける単一始点最短経路 O(V + E)

【引数】
- n: 頂点数 (0-indexed: 0 ~ n-1)
- g: 隣接リスト [[(to, cost), ...], ...]
- s: 始点, t: 終点
"""

import heapq
from collections import deque

# https://github.com/ddfkit/acsampl/blob/main/dijkstra.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def dijkstra(n,g,s=0,inf=10**18):
    d=[inf]*n;d[s]=0;q=[(0,s)]
    while q:
        cd,u=heapq.heappop(q)
        if cd>d[u]:continue
        for v,c in g[u]:
            if d[u]+c<d[v]:d[v]=d[u]+c;heapq.heappush(q,(d[v],v))
    return d

# https://github.com/ddfkit/acsampl/blob/main/dijkstra.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def dijkstra_path(n,g,s,t,inf=10**18):
    d=[inf]*n;p=[-1]*n;d[s]=0;q=[(0,s)]
    while q:
        cd,u=heapq.heappop(q)
        if u==t:break
        if cd>d[u]:continue
        for v,c in g[u]:
            if d[u]+c<d[v]:d[v]=d[u]+c;p[v]=u;heapq.heappush(q,(d[v],v))
    if d[t]==inf:return d[t],[]
    cur=t;path=[]
    while cur!=-1:path.append(cur);cur=p[cur]
    return d[t],path[::-1]

# https://github.com/ddfkit/acsampl/blob/main/dijkstra.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def bfs01(n,g,s=0,inf=10**18):
    d=[inf]*n;d[s]=0;q=deque([s])
    while q:
        u=q.popleft()
        for v,c in g[u]:
            if d[u]+c<d[v]:
                d[v]=d[u]+c
                if c:q.append(v)
                else:q.appendleft(v)
    return d

if __name__ == "__main__":
    g = [
        [(1, 2), (2, 5)],
        [(2, 1), (3, 4)],
        [(3, 1)],
        [(4, 3)],
        []
    ]
    d = dijkstra(5, g, 0)
    assert d == [0, 2, 3, 4, 7]
    cost, path = dijkstra_path(5, g, 0, 4)
    assert cost == 7 and path == [0, 1, 2, 3, 4]

    g01 = [[(1, 0), (2, 1)], [(2, 0)], []]
    assert bfs01(3, g01, 0) == [0, 0, 0]
    print("dijkstra.py: tests passed!")
